def convert_jsonrpc_error(error: dict[str, int | str | None]) -> dict[str, int | str | None]:
    """Convert a JSON-RPC error into an MCP error object. error: a JSON-RPC error object with code, message, and optional data -> an MCP error object with code, message, and data."""
    if not isinstance(error, dict):
        raise ValueError("error must be a dictionary")

    if "code" not in error or "message" not in error:
        raise ValueError("error must contain 'code' and 'message' fields")

    code = error["code"]
    message = error["message"]
    data = error.get("data")

    if not isinstance(code, int):
        raise ValueError("error code must be an integer")

    if not isinstance(message, str):
        raise ValueError("error message must be a string")

    return {"code": code, "message": message, "data": data}

