def classify_inbound_request(
    body: Mapping[str, Any],
    headers: Mapping[str, str] | None = None,
) -> dict[str, Any] | dict[str, Any]:
    """Validate and classify an inbound JSON-RPC request according to the modern protocol. body: decoded JSON-RPC request mapping. headers: transport headers or None. Example: {'jsonrpc': '2.0', 'method': 'mcp.list', 'params': {'_meta': {'protocol_version': '2024-10-01', 'client_capabilities': {}}}} -> classification result."""

    try:
        result = _classify_inbound_request(
            body=body,
            headers=headers,
            supported_modern_versions=MODERN_PROTOCOL_VERSIONS
        )

        if isinstance(result, InboundLadderRejection):
            return {
                "type": "rejection",
                "code": -32602,  # INVALID_PARAMS
                "message": result.message,
                "data": getattr(result, "data", None)
            }
        else:
            return {
                "type": "route",
                "protocol_version": result.protocol_version,
                "client_capabilities": result.client_capabilities,
                "client_info": result.client_info
            }

    except Exception as e:
        raise ValueError(f"classify_inbound_request failed: {str(e)}") from e

import re
from typing import List, Dict, Any
from dataclasses import dataclass

# Define the regex pattern as a constant
TOOL_NAME_REGEX = re.compile(r'^[A-Za-z0-9._-]+$')

# Mock the ToolNameValidationResult since we can't import mcp_types
@dataclass
class ToolNameValidationResult:
    is_valid: bool
    warnings: List[str]

def validate_tool_name(name: str) -> Dict[str, Any]:
    """Validate a tool name according to the SEP-986 specification. name: The tool name to validate, e.g. 'my_tool' -> {"is_valid": true, "warnings": []}."""
    warnings: List[str] = []

    # Check for empty name
    if not name:
        return {
            "is_valid": False,
            "warnings": ["Tool name cannot be empty"],
        }

    # Check length
    if len(name) > 128:
        return {
            "is_valid": False,
            "warnings": [f"Tool name exceeds maximum length of 128 characters (current: {len(name)})"],
        }

    # Check for problematic patterns (warnings, not validation failures)
    if " " in name:
        warnings.append("Tool name contains spaces, which may cause parsing issues")

    if "," in name:
        warnings.append("Tool name contains commas, which may cause parsing issues")

    # Check for potentially confusing leading/trailing characters
    if name.startswith("-") or name.endswith("-"):
        warnings.append("Tool name starts or ends with a dash, which may cause parsing issues in some contexts")

    if name.startswith(".") or name.endswith("."):
        warnings.append("Tool name starts or ends with a dot, which may cause parsing issues in some contexts")

    # Check for invalid characters
    if not TOOL_NAME_REGEX.fullmatch(name):
        # Find all invalid characters (unique, preserving order)
        invalid_chars: List[str] = []
        seen: set[str] = set()
        for char in name:
            if not re.match(r"[A-Za-z0-9._-]", char) and char not in seen:
                invalid_chars.append(char)
                seen.add(char)

        warnings.append(f"Tool name contains invalid characters: {', '.join(repr(c) for c in invalid_chars)}")
        warnings.append("Allowed characters are: A-Z, a-z, 0-9, underscore (_), dash (-), and dot (.)")

        return {
            "is_valid": False,
            "warnings": warnings
        }

    return {
        "is_valid": True,
        "warnings": warnings
    }

