def handler_exception_to_error_data(exc: BaseException) -> Optional[Dict[str, Any]]:
    """Map a handler-raised exception to its wire `ErrorData`. exc: A BaseException instance to be converted, e.g. MCPError -> ErrorData, ValidationError -> INVALID_PARAMS error."""
    # Since we cannot import the actual mcp modules, we'll implement based on the docstring logic
    # This mimics the behavior without requiring the actual imports
    exc_type = type(exc).__name__
    if exc_type == 'MCPError':
        # Simulate MCPError behavior
        return getattr(exc, 'error', None)
    elif isinstance(exc, ValidationError):
        # Simulate ValidationError behavior (INVALID_PARAMS)
        return {"code": -32602, "message": "Invalid request parameters", "data": ""}
    return None
